sys_script.script:
(function executeRule(current, previous /*null when async*/ ) {
    var newParentGr = current.parent.getRefRecord();
    if (current.parent.changes()) {
        var errorMessageForIncorrectOrder = new WPEntityUtils().isOrderOfParentCorrect(current, newParentGr);
        if (!gs.nil(errorMessageForIncorrectOrder)) {
            current.setAbortAction(true);
            gs.addErrorMessage(errorMessageForIncorrectOrder);
            return;
        } else {
            var errorMessageForCyclicOrder = new WPEntityUtils().isCyclic(current.getUniqueValue(), newParentGr.getUniqueValue());
            if (!gs.nil(errorMessageForCyclicOrder)) {
                current.setAbortAction(true);
                gs.addErrorMessage(errorMessageForCyclicOrder);
                return;
            }
        }

        if (current.update_type == WPConstants.ENTITY_UPDATE_TYPE.ENTITY_TYPE_UPDATE) {
            current.update_type = WPConstants.ENTITY_UPDATE_TYPE.ENTITY_TYPE_AND_PARENT_UPDATE;
        } else if (gs.nil(current.update_type)) {
            current.update_type = WPConstants.ENTITY_UPDATE_TYPE.PARENT_UPDATE;
        }
    }

    if (current.entity_type.changes()) {
        var errorMessageForIncorrectEntityType = new WPEntityUtils().isEntityTypeCorrect(current, newParentGr);
        if (!gs.nil(errorMessageForIncorrectEntityType)) {
            current.setAbortAction(true);
            gs.addErrorMessage(errorMessageForIncorrectEntityType);
            return;
        }

        if (current.update_type == WPConstants.ENTITY_UPDATE_TYPE.PARENT_UPDATE) {
            current.update_type = WPConstants.ENTITY_UPDATE_TYPE.ENTITY_TYPE_AND_PARENT_UPDATE;
        } else if (gs.nil(current.update_type)) {
            current.update_type = WPConstants.ENTITY_UPDATE_TYPE.ENTITY_TYPE_UPDATE;
        }
    }

})(current, previous);
